ARATOR . 'autoload.php'; } public function listFiles() { if ($this->uploadMgr) { $prefix = ''; $marker = ''; $limit = 1; $listFiles = $this->bucketMgr->listFiles($this->bucket, $prefix, $marker, $limit); if (!$listFiles[0]) { print '<div class="error"><p>'.$listFiles[1]->message().'</p></div>'; $this->accessed = false; $this->uploadMgr = null; } } } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { if (!$this->uploadMgr) { $this->includes(); $this->auth = new Auth($this->AccessKey, $this->SecretKey); $this->token = $this->auth->uploadToken($this->bucket); $this->bucketMgr = new BucketManager($this->auth); $this->uploadMgr = new UploadManager(); $this->accessed = true; } } } public function is_object_exist($destination_path) { $destination_path = preg_replace('/^\/*/i', '', $destination_path); $this->access_service(); list($ret, $err) = $this->bucketMgr->stat($this->bucket, $destination_path); return $err=== null; } public function upload($destination_path, $source_path) { $this->access_service(); if (!file_exists($source_path) || !filesize($source_path)) return false; set_time_limit($this->options->qc_stress_timeout); if ($this->is_object_exist($destination_path)) { if ($this->options->cloud_storage_override) { $this->delete_object($destination_path); } else { return true; } } $destination_path = preg_replace('/^\//', '', $destination_path); list($ret, $err) = $this->uploadMgr->putFile($this->token, $destination_path, $source_path); do_action( 'qqworld-collector-log', $this->log_id, 'QiNiu:', print_r($ret, true) . "\r\n" . print_r($err, true) ); return isset($ret['key']) && $ret['key'] && $err === null; } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); $this->access_service(); $err = $this->bucketMgr->delete($this->bucket, $object); return $err === null; } public function add_could_storage_form($guid) { $this->access_service(); $this->listFiles(); require QQWORLD_COLLECTOR_DIR .